#include <stdio.h>
/* ex06：CDMA 码分多址——用「正交码片」让多路信号同时同频传输
 * 每个站分配一个码片序列（Walsh 码，两两正交：内积为 0）。
 * 发送 1 -> 发自己的码片；发送 0 -> 发码片的反码；静默 -> 不发。
 * 接收端用「内积 / 码片长度」解码：
 *   结果 = +1 表示该站发了 1，-1 表示发了 0，0 表示该站静默。
 * 正交性保证「别人的信号内积后为 0」，所以能各取所需。*/
int main(void) {
    /* 4 个站的码片序列（两两正交） */
    int A[4] = { 1,  1,  1,  1};
    int B[4] = { 1,  1, -1, -1};
    int C[4] = { 1, -1,  1, -1};
    int D[4] = { 1, -1, -1,  1};
    int *st[4] = {A, B, C, D};
    const char *nm[4] = {"A", "B", "C", "D"};
    int sending[4] = {1, 0, -1, 1};      /* 1=发1, 0=发0, -1=静默 */

    int sum[4] = {0, 0, 0, 0};           /* 公共信道上的叠加信号 */

    printf("码片序列（长度 4，两两正交）\n");
    for (int s = 0; s < 4; s++) {
        printf("  %s: ", nm[s]);
        for (int k = 0; k < 4; k++) printf("%+d ", st[s][k]);
        printf("  发送=%s\n", sending[s] == 1 ? "1" : sending[s] == 0 ? "0" : "静默");
    }

    /* 叠加：发 1 加上码片，发 0 减去码片 */
    printf("\n逐个码片叠加：\n");
    for (int s = 0; s < 4; s++) {
        if (sending[s] == -1) continue;
        int sign = (sending[s] == 1) ? +1 : -1;
        printf("  %s %s [%+d %+d %+d %+d]\n", nm[s], sign > 0 ? "+" : "-",
               sign * st[s][0], sign * st[s][1], sign * st[s][2], sign * st[s][3]);
        for (int k = 0; k < 4; k++) sum[k] += sign * st[s][k];
    }
    printf("  信道信号 S = [%+d %+d %+d %+d]\n", sum[0], sum[1], sum[2], sum[3]);

    /* 解码：内积 / 4 */
    printf("\n接收端解码（内积 / 4）：\n");
    printf("%-6s %-22s %-10s %s\n", "站", "内积 S·码片", "解码值", "原始数据");
    for (int s = 0; s < 4; s++) {
        int dot = 0;
        for (int k = 0; k < 4; k++) dot += sum[k] * st[s][k];
        double d = dot / 4.0;
        printf("%-6s %-22d %-10.0f %s\n", nm[s], dot, d,
               d > 0.5 ? "1" : d < -0.5 ? "0" : "静默");
    }
    printf("\n结论：4 个站同时同频发送，接收端仍能各自解出正确数据 ——\n");
    printf("      靠的是码片「两两正交」，别人的信号在自己码片上内积为 0。\n");
    printf("      这就是 3G（CDMA2000/WCDMA）的物理层基础。\n");
    return 0;
}
